alter table public.messages add constraint messages_has_context CHECK (offer_id IS NOT NULL OR order_id IS NOT NULL OR listing_id IS NOT NULL);
alter table public.messages add constraint messages_has_words CHECK (char_length(btrim(body)) > 0 OR cardinality(attachments) > 0);
alter table public.messages add constraint messages_kind_check CHECK (kind = ANY (ARRAY['message'::text, 'event'::text]));
alter table public.messages add constraint messages_listing_id_fkey FOREIGN KEY (listing_id) REFERENCES public.listings(id) ON DELETE CASCADE;
alter table public.messages add constraint messages_offer_id_fkey FOREIGN KEY (offer_id) REFERENCES public.offers(id) ON DELETE CASCADE;
alter table public.messages add constraint messages_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(id) ON DELETE CASCADE;
alter table public.messages add constraint messages_pkey PRIMARY KEY (id);
